import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { runOpenDatasetExperiments } from "./openDatasetExperiments.js";
import { runOpenExperiments } from "./openExperiments.js";
import { runPageLink } from "./pageLink.js";
import { runStartDataset } from "./startDataset.js";
import { runStartTemplatePreview } from "./startTemplatePreview.js";
vi.mock("../config.js", () => ({
    getOrCreateInstallId: () => "test-install-id",
    getConfig: () => ({
        serviceUrl: "https://test.invalid/",
        apiKey: "test-api-key",
    }),
}));
const platform = {};
const id = "12345678-1234-4234-8234-123456789012";
const originalArgv = process.argv;
let output;
beforeEach(() => {
    output = [];
    vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
        output.push(String(chunk));
        return true;
    });
    vi.spyOn(globalThis, "fetch").mockRejectedValue(new Error("Link commands must not access the network"));
});
afterEach(() => {
    process.argv = originalArgv;
    vi.restoreAllMocks();
});
function args(...values) {
    process.argv = ["node", "command.js", ...values];
}
function expectLink(path, accessesNetwork = false) {
    expect(output).toHaveLength(1);
    expect(JSON.parse(output[0])).toEqual({
        event: "link",
        url: `https://test.invalid${path}`,
    });
    if (!accessesNetwork) {
        expect(globalThis.fetch).not.toHaveBeenCalled();
    }
}
describe("product page links", () => {
    it("encodes the function key in dataset and preview links", async () => {
        args("agent/reply", id);
        await runStartDataset(platform, "test");
        expectLink(`/trace-functions/agent%2Freply/datasets/${id}`);
        output = [];
        vi.mocked(globalThis.fetch).mockResolvedValueOnce(Response.json({ id }));
        args("agent/reply");
        await runStartTemplatePreview(platform, "test");
        expectLink(`/plugin/trace-functions/agent%2Freply/template-preview?ticket=${id}`, true);
        expect(globalThis.fetch).toHaveBeenCalledWith("https://test.invalid/api/plugin/handoff-tickets", expect.objectContaining({
            method: "POST",
            headers: expect.objectContaining({
                Authorization: "Bearer test-api-key",
                "Content-Type": "application/json",
            }),
        }));
        const [, request] = vi.mocked(globalThis.fetch).mock.calls[0];
        expect(JSON.parse(String(request?.body))).toEqual({
            kind: "template.preview",
            ttlSeconds: 1800,
        });
    });
    it("rejects an invalid template-preview ticket response", async () => {
        vi.mocked(globalThis.fetch).mockResolvedValueOnce(Response.json({ id: "not-a-ticket-id" }));
        args("agent/reply");
        await expect(runStartTemplatePreview(platform, "test")).rejects.toThrow("invalid ticket response");
        expect(output).toHaveLength(0);
    });
    it("does not emit a preview link without an organization ticket", async () => {
        vi.mocked(globalThis.fetch).mockResolvedValueOnce(new Response(null, { status: 503 }));
        args("agent/reply");
        await expect(runStartTemplatePreview(platform, "test")).rejects.toThrow("Could not open template preview (HTTP 503).");
        expect(output).toHaveLength(0);
    });
    it("preserves selected experiments and the uncached token lens", async () => {
        args(id, "--show-tokens", "--uncached");
        await runOpenExperiments(platform);
        expectLink(`/experiments?testRunIds=${id}&tokens=1&tokenType=uncached`);
    });
    it("preserves dataset experiment scope", async () => {
        args(id);
        await runOpenDatasetExperiments(platform);
        expectLink(`/experiments?datasetId=${id}`);
    });
    it("prints app paths and rejects removed duplicate surfaces", () => {
        args("/experiments?experimentGroupId=group");
        runPageLink();
        expectLink("/experiments?experimentGroupId=group");
        for (const path of [
            "/studio",
            "/trace-plan/plan-1",
            "/trace-plans/latest",
            "/plugin/trace-plan/plan-1",
            "/plugin/experiments",
            "/plugin/trace-functions/fn/datasets/dataset-1",
            "/plugin/../studio",
            "/plugin/%2e%2e/studio",
            "/studio/experiments",
            "//example.com",
            "https://example.com",
        ]) {
            args(path);
            expect(() => runPageLink()).toThrow("Provide an app page path");
        }
    });
});
